INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$adult$q$, 0, $q$Jeûner avec sincérité$q$, $q$Fast with sincerity$q$, $q$صيام اليوم$q$, $q$Le jeûne du mois de Ramadan est une obligation (Coran). Renouvelez votre intention chaque jour et gardez le jeûne pour Allah seul.$q$, $q$Fasting in the month of Ramadan is an obligation (Qur’an). Renew your intention each day and fast for Allah alone.$q$, $q$$q$, $q$/coran/2$q$, $q$Coran 2:183 et 2:185.$q$, 1, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$adult$q$ AND day = 0 AND title_fr = $q$Jeûner avec sincérité$q$);

INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$adult$q$, 0, $q$Prendre le suhur$q$, $q$Eat the pre-dawn meal (suhur)$q$, $q$السحور$q$, $q$Le Prophète ﷺ a dit de prendre le repas d’avant l’aube : il y a une bénédiction dans le suhur.$q$, $q$The Prophet ﷺ said to take the pre-dawn meal: there is blessing in suhur.$q$, $q$تَسَحَّرُوا فَإِنَّ فِي السَّحُورِ بَرَكَةً$q$, $q$$q$, $q$Sahih al-Bukhari, Livre du jeûne (Kitab as-Sawm), chapitre de la bénédiction du suhur ; rapporté par Anas ibn Malik.$q$, 2, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$adult$q$ AND day = 0 AND title_fr = $q$Prendre le suhur$q$);

INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$adult$q$, 0, $q$Rompre le jeûne sans tarder$q$, $q$Break the fast promptly$q$, $q$تعجيل الفطر$q$, $q$Les gens resteront dans le bien tant qu’ils se hâtent de rompre le jeûne, une fois le coucher du soleil établi.$q$, $q$People will remain in good as long as they hasten to break the fast, once sunset is established.$q$, $q$لاَ يَزَالُ النَّاسُ بِخَيْرٍ مَا عَجَّلُوا الْفِطْرَ$q$, $q$$q$, $q$Sahih al-Bukhari, Livre du jeûne, chapitre de la hâte de rompre le jeûne ; rapporté par Sahl ibn Sa‘d.$q$, 3, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$adult$q$ AND day = 0 AND title_fr = $q$Rompre le jeûne sans tarder$q$);

INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$adult$q$, 0, $q$Prière de nuit (tarawih)$q$, $q$Night prayer (tarawih)$q$, $q$قيام الليل$q$, $q$Celui qui accomplit la prière de nuit pendant Ramadan avec foi et en espérant la récompense d’Allah, ses péchés passés lui seront pardonnés (hadith rapporté par Abu Hurayra). Notez vos tarawih dans la case dédiée.$q$, $q$Whoever prays at night in Ramadan out of faith and hoping for Allah’s reward, his previous sins will be forgiven (narrated by Abu Hurayra). Record your tarawih in the dedicated box.$q$, $q$مَنْ قَامَهُ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ$q$, $q$$q$, $q$Sahih al-Bukhari, Livre de la prière des tarawih (Salat at-Tarawih) ; rapporté par Abu Hurayra.$q$, 4, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$adult$q$ AND day = 0 AND title_fr = $q$Prière de nuit (tarawih)$q$);

INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$adult$q$, 0, $q$Lire le Coran$q$, $q$Read the Qur’an$q$, $q$تلاوة القرآن$q$, $q$Ramadan est le mois du Coran. Le Prophète ﷺ le révisait chaque nuit de Ramadan avec Jibril. Lisez votre part du jour : le plan « Lire le Coran en 30 jours » vous guide.$q$, $q$Ramadan is the month of the Qur’an. The Prophet ﷺ reviewed it every night of Ramadan with Jibril. Read your portion for the day: the “Read the Qur’an in 30 days” plan guides you.$q$, $q$$q$, $q$/coran$q$, $q$Coran 2:185 ; Sahih al-Bukhari, Livre des vertus / des prophètes, hadith d’Ibn ‘Abbas sur la générosité du Prophète ﷺ et la révision du Coran avec Jibril.$q$, 5, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$adult$q$ AND day = 0 AND title_fr = $q$Lire le Coran$q$);

INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$adult$q$, 0, $q$Garder sa langue et ses actes$q$, $q$Guard your tongue and your actions$q$, $q$حفظ اللسان$q$, $q$Celui qui n’abandonne pas la parole mensongère, l’acte qui va avec et l’ignorance, Allah n’a pas besoin qu’il abandonne sa nourriture et sa boisson. Le jeûne se vit aussi dans les paroles.$q$, $q$Whoever does not give up false speech, acting on it, and ignorance, Allah has no need of him giving up his food and drink. Fasting is also lived in words.$q$, $q$مَنْ لَمْ يَدَعْ قَوْلَ الزُّورِ وَالْعَمَلَ بِهِ وَالْجَهْلَ فَلَيْسَ لِلَّهِ حَاجَةٌ أَنْ يَدَعَ طَعَامَهُ وَشَرَابَهُ$q$, $q$$q$, $q$Sahih al-Bukhari, Livre du jeûne ; rapporté par Abu Hurayra.$q$, 6, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$adult$q$ AND day = 0 AND title_fr = $q$Garder sa langue et ses actes$q$);

INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$adult$q$, 0, $q$Donner, même un peu$q$, $q$Give, even a little$q$, $q$الصدقة$q$, $q$Le Prophète ﷺ était le plus généreux des gens, et il l’était davantage encore pendant Ramadan. Donnez quelque chose aujourd’hui, même modeste.$q$, $q$The Prophet ﷺ was the most generous of people, and even more so in Ramadan. Give something today, however small.$q$, $q$$q$, $q$$q$, $q$Sahih al-Bukhari, hadith d’Ibn ‘Abbas sur la générosité du Prophète ﷺ en Ramadan.$q$, 7, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$adult$q$ AND day = 0 AND title_fr = $q$Donner, même un peu$q$);

INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$adult$q$, 0, $q$Nourrir une personne qui jeûne$q$, $q$Feed someone who is fasting$q$, $q$تفطير الصائم$q$, $q$Celui qui offre de quoi rompre le jeûne à une personne qui jeûne aura la même récompense qu’elle, sans que la sienne soit diminuée. Un repas partagé, une datte, un verre d’eau comptent.$q$, $q$Whoever provides food for a fasting person to break his fast will have the same reward as that person, without diminishing the faster’s reward. A shared meal, a date, a glass of water all count.$q$, $q$مَنْ فَطَّرَ صَائِمًا كَانَ لَهُ مِثْلُ أَجْرِهِ غَيْرَ أَنَّهُ لاَ يَنْقُصُ مِنْ أَجْرِ الصَّائِمِ شَيْئًا$q$, $q$$q$, $q$Jami‘ at-Tirmidhi, Livre du jeûne ; rapporté par Zayd ibn Khalid al-Juhani ; at-Tirmidhi : « hasan sahih ».$q$, 8, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$adult$q$ AND day = 0 AND title_fr = $q$Nourrir une personne qui jeûne$q$);

INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$adult$q$, 1, $q$Renouveler son intention$q$, $q$Renew your intention$q$, $q$تجديد النية$q$, $q$Les actes valent selon les intentions. Au premier jour, posez votre intention pour tout le mois : jeûne, prière, Coran, partage.$q$, $q$Deeds are judged by intentions. On the first day, set your intention for the whole month: fasting, prayer, Qur’an, giving.$q$, $q$$q$, $q$$q$, $q$Sahih al-Bukhari, Livre de la révélation, premier hadith ; rapporté par ‘Umar ibn al-Khattab.$q$, 0, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$adult$q$ AND day = 1 AND title_fr = $q$Renouveler son intention$q$);

INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$adult$q$, 21, $q$Les dix dernières nuits commencent$q$, $q$The last ten nights begin$q$, $q$العشر الأواخر$q$, $q$Le Prophète ﷺ s’isolait en retraite (i‘tikaf) dans les dix dernières nuits de Ramadan et disait de rechercher la Nuit du Destin durant celles-ci. Donnez-leur plus de temps, selon vos moyens.$q$, $q$The Prophet ﷺ would observe i‘tikaf in the last ten nights of Ramadan and said to look for the Night of Power in them. Give them more time, as you are able.$q$, $q$تَحَرَّوْا لَيْلَةَ الْقَدْرِ فِي الْعَشْرِ الأَوَاخِرِ مِنْ رَمَضَانَ$q$, $q$$q$, $q$Sahih al-Bukhari, Livre de la retraite (I‘tikaf) et Livre de la Nuit du Destin ; rapporté par ‘A’icha.$q$, 0, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$adult$q$ AND day = 21 AND title_fr = $q$Les dix dernières nuits commencent$q$);

INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$adult$q$, 21, $q$Chercher la Nuit du Destin$q$, $q$Look for the Night of Power$q$, $q$تحري ليلة القدر$q$, $q$Cherchez la Nuit du Destin dans les nuits impaires des dix dernières nuits. Elle vaut mieux que mille mois (Coran). Priez, lisez, invoquez.$q$, $q$Look for the Night of Power in the odd nights of the last ten. It is better than a thousand months (Qur’an). Pray, read, make supplication.$q$, $q$تَحَرَّوْا لَيْلَةَ الْقَدْرِ فِي الْوِتْرِ مِنَ الْعَشْرِ الأَوَاخِرِ مِنْ رَمَضَانَ$q$, $q$/coran/97$q$, $q$Coran 97:1-5 ; Sahih al-Bukhari, Livre de la Nuit du Destin ; rapporté par ‘A’icha.$q$, 1, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$adult$q$ AND day = 21 AND title_fr = $q$Chercher la Nuit du Destin$q$);

INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$adult$q$, 21, $q$Invocation de la Nuit du Destin$q$, $q$Supplication for the Night of Power$q$, $q$دعاء ليلة القدر$q$, $q$‘A’icha demanda ce qu’elle devait dire si elle rencontrait la Nuit du Destin. Le Prophète ﷺ répondit : « Ô Allah, Tu es Pardonneur et Tu aimes le pardon : pardonne-moi. »$q$, $q$‘A’isha asked what to say if she met the Night of Power. The Prophet ﷺ replied: “O Allah, You are Forgiving and You love forgiveness, so forgive me.”$q$, $q$اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي$q$, $q$$q$, $q$Sunan Ibn Majah, Livre de l’invocation (Du‘a’), rapporté par ‘A’icha. Le recueil de at-Tirmidhi la rapporte aussi (numéro à vérifier à la relecture).$q$, 2, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$adult$q$ AND day = 21 AND title_fr = $q$Invocation de la Nuit du Destin$q$);

