INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$adult$q$, 29, $q$Préparer la zakat al-fitr$q$, $q$Prepare zakat al-fitr$q$, $q$زكاة الفطر$q$, $q$La zakat al-fitr est obligatoire pour tout musulman ; elle se verse avant la prière de l’Aïd. Préparez-la avec votre famille.$q$, $q$Zakat al-fitr is obligatory on every Muslim; it is paid before the ‘Id prayer. Prepare it with your family.$q$, $q$$q$, $q$$q$, $q$Sahih al-Bukhari, Livre de la zakat, chapitre de la zakat al-fitr ; rapporté par Ibn ‘Umar. Montant et forme : à préciser par la relecture (selon l’école et le lieu).$q$, 3, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$adult$q$ AND day = 29 AND title_fr = $q$Préparer la zakat al-fitr$q$);

INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$kid$q$, 0, $q$Je lis ou j’écoute un peu de Coran$q$, $q$I read or listen to some Qur’an$q$, $q$أقرأ أو أسمع القرآن$q$, $q$Ramadan est le mois du Coran. Avec un parent, je lis ou j’écoute quelques versets que je connais.$q$, $q$Ramadan is the month of the Qur’an. With a parent, I read or listen to a few verses I know.$q$, $q$$q$, $q$/coran$q$, $q$Coran 2:185.$q$, 1, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$kid$q$ AND day = 0 AND title_fr = $q$Je lis ou j’écoute un peu de Coran$q$);

INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$kid$q$, 0, $q$Je dis de belles paroles$q$, $q$I say kind words$q$, $q$أقول كلمة طيبة$q$, $q$Pendant Ramadan, je fais attention à mes mots : pas de mensonge, pas de dispute. Je parle avec gentillesse.$q$, $q$During Ramadan I am careful with my words: no lies, no arguing. I speak kindly.$q$, $q$$q$, $q$$q$, $q$Sahih al-Bukhari, Livre du jeûne ; rapporté par Abu Hurayra (la parole mensongère).$q$, 2, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$kid$q$ AND day = 0 AND title_fr = $q$Je dis de belles paroles$q$);

INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$kid$q$, 0, $q$Je partage avec les autres$q$, $q$I share with others$q$, $q$أشارك غيري$q$, $q$Le Prophète ﷺ était très généreux en Ramadan. Aujourd’hui, je donne ou je partage quelque chose : un goûter, un jouet, une petite pièce.$q$, $q$The Prophet ﷺ was very generous in Ramadan. Today I give or share something: a snack, a toy, a small coin.$q$, $q$$q$, $q$$q$, $q$Sahih al-Bukhari, hadith d’Ibn ‘Abbas sur la générosité du Prophète ﷺ en Ramadan.$q$, 3, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$kid$q$ AND day = 0 AND title_fr = $q$Je partage avec les autres$q$);

INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$kid$q$, 0, $q$J’aide à préparer la rupture du jeûne$q$, $q$I help prepare the iftar$q$, $q$أساعد في الإفطار$q$, $q$J’aide ma famille à préparer le repas de la rupture ou à mettre la table. Offrir à manger à quelqu’un qui jeûne est une belle action.$q$, $q$I help my family prepare the iftar meal or set the table. Giving food to someone who is fasting is a beautiful deed.$q$, $q$$q$, $q$$q$, $q$Jami‘ at-Tirmidhi, Livre du jeûne ; rapporté par Zayd ibn Khalid al-Juhani.$q$, 4, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$kid$q$ AND day = 0 AND title_fr = $q$J’aide à préparer la rupture du jeûne$q$);

INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$kid$q$, 0, $q$Je suis la prière avec ma famille$q$, $q$I join the prayer with my family$q$, $q$أصلي مع أسرتي$q$, $q$Avec ma famille, je prie ce que je peux, aussi longtemps que je peux. Prier la nuit en Ramadan est une belle habitude.$q$, $q$With my family, I pray what I can, as long as I can. Praying at night in Ramadan is a beautiful habit.$q$, $q$$q$, $q$$q$, $q$Sahih al-Bukhari, Livre de la prière des tarawih ; rapporté par Abu Hurayra.$q$, 5, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$kid$q$ AND day = 0 AND title_fr = $q$Je suis la prière avec ma famille$q$);

INSERT INTO ramadan_items(audience, day, title_fr, title_en, title_ar, text_fr, text_en, text_ar, link, reference, position, enabled)
SELECT $q$kid$q$, 27, $q$Je demande pardon à Allah$q$, $q$I ask Allah for forgiveness$q$, $q$أطلب العفو$q$, $q$Dans les nuits impaires de la fin de Ramadan, on cherche la Nuit du Destin. Avec un parent, je dis : « Ô Allah, Tu es Pardonneur et Tu aimes le pardon : pardonne-moi. »$q$, $q$In the odd nights at the end of Ramadan we look for the Night of Power. With a parent, I say: “O Allah, You are Forgiving and You love forgiveness, so forgive me.”$q$, $q$اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي$q$, $q$$q$, $q$Sunan Ibn Majah, Livre de l’invocation ; rapporté par ‘A’icha.$q$, 1, false
WHERE NOT EXISTS (SELECT 1 FROM ramadan_items WHERE audience = $q$kid$q$ AND day = 27 AND title_fr = $q$Je demande pardon à Allah$q$);
